                centers.append((r,c))
    full_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    full_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    for r,c in centers:
        # Extend a center by a perpendicular line, toward the other separator
        # of the same orientation; demo 1's horizontal separator is row 6.
        if c in full_cols:
            # vertical-divider source: across row, flared where crossing other vertical dividers
            for x in range(w):
                if out[r][x] == 0: out[r][x] = 1
            for x in full_cols:
